// Bundles the compiled model and engine (CommonJS in out/) into media/machina.js for the webview,
// exposing them as `window.Machina`. Run after tsc (part of `npm run compile`).
//
// Why: the diagram editor's simulator and validation in the webview (media/editor.js) use exactly the same
// analysis and execution code as the extension (src/model.ts, src/engine.ts). The webview is a plain
// browser page without a module loader, and its Content Security Policy only runs nonce-tagged <script>
// files (see editorProvider.ts), so the code must arrive as one ordinary script file.
//
// Approach: a minimal CommonJS loader instead of a bundler dependency. Each compiled module's source is
// pasted verbatim into a factory function `function (exports, require, module) { … }` registered under its
// relative module id ('./model', './engine'), so it sees the same three free variables as under Node.js.
// The bundle's own `require` runs a factory the first time its module is requested and caches the module
// object; the cache entry is created before the factory runs, so even a circular import would get the
// (partially filled) exports instead of recursing forever. Both tsc's `exports.x = …` output and code that
// replaces `module.exports` work, because `require` returns `module.exports` after the factory has run.
// Only the bundled modules can be required (engine.js requires "./model"); the build fails if a module
// requires anything else, and the bundle's `require` throws for an unknown id.
//
// The exports of all modules are merged into the single namespace `window.Machina`, so an export name may
// occur in only one module; otherwise one module's export would silently replace the other's. The build
// therefore loads the compiled modules in Node.js, compares their export names and fails with an error
// listing any name exported by more than one module.
//
// The script is plain Node.js (no TypeScript) and has no dependencies besides fs and path.
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
// Compiled modules to include, by file name in out/ (without .js).
const modules = ['model', 'engine'];

/** Reports a build error and exits with a failure status, so `npm run compile` stops. */
function fail(message) {
    console.error(`bundle-webview: ${message}`);
    process.exit(1);
}

// Read the modules. The `//# sourceMappingURL=` line tsc appends is removed: it refers to the source map of
// the individual out/ file, which would not apply inside the bundle.
const sources = modules.map(name => ({
    name,
    code: fs.readFileSync(path.join(root, 'out', `${name}.js`), 'utf8').replace(/^\/\/# sourceMappingURL=.*$/m, '')
}));

// Every require() must name another bundled module; the loader cannot provide anything else.
for (const { name, code } of sources) {
    for (const [, id] of code.matchAll(/\brequire\(\s*["']([^"']*)["']\s*\)/g)) {
        if (!modules.some(m => `./${m}` === id)) {
            fail(`out/${name}.js requires '${id}', which is not part of the webview bundle.`);
        }
    }
}

// Export-name collisions: which module exports each name (as Node.js sees the compiled modules).
// `__esModule` is defined non-enumerable by tsc and is therefore not listed by Object.keys.
const owners = new Map();
for (const name of modules) {
    for (const key of Object.keys(require(path.join(root, 'out', `${name}.js`)))) {
        owners.set(key, [...(owners.get(key) ?? []), name]);
    }
}
const clashes = [...owners].filter(([, names]) => names.length > 1);
if (clashes.length) {
    fail(`export name collision in window.Machina: ${clashes.map(([key, names]) => `'${key}' (${names.join(', ')})`).join('; ')}.`);
}

// Wrap each module in a define() call.
const parts = sources.map(({ name, code }) => `    define('./${name}', function (exports, require, module) {\n${code}\n    });`);

// The bundle: an IIFE (so nothing but window.Machina leaks into the page's global scope) containing the
// loader, the module definitions and the export (export names are known to be distinct, see above).
const bundle = `// Generated by scripts/bundle-webview.js from ${modules.map(m => `out/${m}.js`).join(' and ')}. Do not edit.
(function () {
    'use strict';
    const registry = {};
    const factories = {};
    function define(name, factory) {
        factories[name] = factory;
    }
    function require(name) {
        if (!registry[name]) {
            if (!factories[name]) {
                throw new Error('machina.js: module ' + name + ' is not bundled');
            }
            const module = (registry[name] = { exports: {} });
            factories[name](module.exports, require, module);
        }
        return registry[name].exports;
    }
${parts.join('\n')}
    window.Machina = Object.assign({}, ${modules.map(m => `require('./${m}')`).join(', ')});
})();
`;
// Written into media/, which is the webview's only local resource root.
fs.writeFileSync(path.join(root, 'media', 'machina.js'), bundle);
